this["app"]["templates"]["p_about"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" class="rf-header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1 id=\'about_heading\'>About the App</h1>\n</div>\n\n<div data-role="content" class="rf rf-about">\n    <div class="rf-section" style="margin-top:16px;">\n        <div class="rf-section-title">Introduction</div>\n        <p class="rf-body-text">This app features 138 species of dragonflies and damselflies recorded in Singapore. It is designed to provide a quick and convenient reference for identifying and learning about Singapore’s Odonata, with information readily available at your fingertips.</p>\n        <p class="rf-body-text">For more detailed information, we recommend referring to authoritative reference books, such as:</p>\n        <ul class="rf-booklist">\n            <li>A Photographic Field Guide to the Dragonflies &amp; Damselflies of Singapore &mdash; Robin Ngiam &amp; Marcus Ng</li>\n            <li>A Photographic Guide to the Dragonflies of Singapore &mdash; Tang Hung Bun, Wang Luan Keng &amp; Matti Hämäläinen</li>\n            <li>Dragonflies of Peninsular Malaysia and Singapore &mdash; A. G. Orr</li>\n        </ul>\n    </div>\n\n    <div class="rf-section">\n        <div class="rf-section-title">Dragonflies of Singapore Facebook Group</div>\n        <p class="rf-body-text">The <a target="_blank" href="https://www.facebook.com/groups/295432323905656/" class="rf-link-btn">Dragonflies of Singapore Facebook Group</a> is a community of dragonfly professionals, experts and enthusiasts who come together to observe, document, discuss and research dragonflies and damselflies in Singapore.</p>\n    </div>\n\n    <div class="rf-section">\n        <div class="rf-section-title">App Development</div>\n        <p class="rf-body-text">This app is based on a framework originally developed by the Biological Records Centre UK (as of 2014) (BRC) mobile development team and subsequently modified by Soon Chye.</p>\n    </div>\n</div>';}return __p};

