this["app"]["templates"]["p_species-info"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" class="rf-header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1>Species Info</h1>\n</div>\n\n<div data-role="content" class="rf rf-info">\n\n    <div class="rf-nav-list">\n        <a href=\'#species-differences\' class="rf-nav-row">\n            <span class="rf-nav-icon rf-nav-icon-teal"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"><line x1="12" y1="4" x2="12" y2="20"></line><path d="M12 8c-3-3-8-3-9 0 1 3 6 3 9 0"></path><path d="M12 8c3-3 8-3 9 0-1 3-6 3-9 0"></path></svg></span>\n            <span class="rf-nav-label">Differences between Dragonfly &amp; Damselfly</span>\n            <svg class="rf-nav-chevron" viewBox="0 0 24 24" width="16" height="16"><path d="M9 6l6 6-6 6"></path></svg>\n        </a>\n        <a href=\'#species-anatomy\' class="rf-nav-row">\n            <span class="rf-nav-icon rf-nav-icon-teal"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"><path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z"></path><circle cx="12" cy="12" r="3"></circle></svg></span>\n            <span class="rf-nav-label">Anatomy</span>\n            <svg class="rf-nav-chevron" viewBox="0 0 24 24" width="16" height="16"><path d="M9 6l6 6-6 6"></path></svg>\n        </a>\n        <a href=\'#species-terms\' class="rf-nav-row">\n            <span class="rf-nav-icon rf-nav-icon-copper"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"><circle cx="12" cy="12" r="9"></circle><line x1="12" y1="11" x2="12" y2="16"></line><circle cx="12" cy="8" r="0.6" fill="currentColor" stroke="none"></circle></svg></span>\n            <span class="rf-nav-label">Technical Terms</span>\n            <svg class="rf-nav-chevron" viewBox="0 0 24 24" width="16" height="16"><path d="M9 6l6 6-6 6"></path></svg>\n        </a>\n    </div>\n</div>';}return __p};

this["app"]["templates"]["p_species-terms"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" class="rf-header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1>Technical Terms</h1>\n</div>\n\n<div data-role="content" class="rf rf-terms">\n    <div class="rf-glossary">\n        <div class="rf-term">\n            <div class="rf-term-name">Accessory genitalia</div>\n            <p class="rf-term-def">The structure on the underside of <b>S2</b> and <b>S3 </b>of the male\'s abdomen that holds sperm prior to\n                copulation.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Anal appendages</div>\n            <p class="rf-term-def">The \'claspers\' at the tip of the male\'s\n                abdomen that grasp the female during copulation.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Antenodal cross-veins</div>\n            <p class="rf-term-def">Veins at right angles to the <b>costa</b>,\n                between the body and the node.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Copulating pair</div>\n            <p class="rf-term-def">Male and female mating in the \'wheel\' position.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Costa</div>\n            <p class="rf-term-def">The front vein, which forms the leading edge of the\n                wing.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Emergent</div>\n            <p class="rf-term-def">Adult that has recently emerged from water, showing\n                reflective wings, white wing-spots and weak flight.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Exuviae</div>\n            <p class="rf-term-def">Larval skins after adults have emerged.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Frons</div>\n            <p class="rf-term-def">The uppermost part of the front of the head (\'face\'),\n                most prominent in dragonflies.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Immature</div>\n            <p class="rf-term-def">An adult that has not yet attained the full colouring\n                typically associated with sexual maturity.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Node (or nodus)</div>\n            <p class="rf-term-def">The notch half-way along the leading edge of\n                the wing.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Obelisk position</div>\n            <p class="rf-term-def">Position adopted by some dragonflies where\n                the abdomen is pointed towards the sun to avoid overheating.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Ovipositing</div>\n            <p class="rf-term-def">Laying eggs into plant material, debris or water, alone or with\n                males still attached.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Ovipositor</div>\n            <p class="rf-term-def">The blade-like egg-laying structure under <b>S8&ndash;10\n                </b>of female Dragonflies that deposits eggs into plant material or\n                substrates.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Pronotum</div>\n            <p class="rf-term-def">A shield-like plate that covers the top of the front\n                of the thorax in dragonflies or prothorax in damselflies.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Pruinescence</div>\n            <p class="rf-term-def">The waxy bloom that gives some Dragonflies a\n                powder blue colour.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">S2, S3, S8&ndash;10 etc.</div>\n            <p class="rf-term-def">Abbreviations used for the number, or\n                range, of the abdominal or antennal segment(s), counted from the\n                base.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Shoulder stripes</div>\n            <p class="rf-term-def">The pair of stripes on the top of the thorax,\n                technically known as antehumeral stripes.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Tandem</div>\n            <p class="rf-term-def">A pair of dragonflies with the male clasping the female behind\n                the head are said to be \'in tandem\'; they may go on to copulate\n                or oviposit.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Teneral</div>\n            <p class="rf-term-def">A newly-emerged adult Dragonfly, with soft cuticle,\n                lacking the full adult colouration and often with shiny wings.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Vulvar scale</div>\n            <p class="rf-term-def">The sometimes prominent flap below <b>S8</b>,\n                present in dragonflies (never damselflies) that lay eggs freely onto\n                the water surface.</p>\n        </div>\n        <div class="rf-term">\n            <div class="rf-term-name">Wing-spot</div>\n            <p class="rf-term-def">The dark or coloured cell along the leading edge of\n                the wing, towards the tip, technically known as the pterostigma.</p>\n        </div>\n    </div>\n</div>';}return __p};

