/******************************************************************************
 * List page view.
 *****************************************************************************/
define('views/p_list',[
    'views/_page',
    'views/list',
    'views/list_controls',
    'views/dialog_download',
    'views/dialog_add_homescreen',
    'helpers/browser',
    'tripjs',
    'templates'
], function (DefaultPage, ListView, ListControlsView, download, addHomescreenDialog,
             browser) {
    'use strict';

    var Page = DefaultPage.extend({
        id: 'list',

        template: app.templates.p_list,

        events: {
            'click .list-controls-done-button': 'toggleListControls',
            'click #list-controls-button': 'toggleListControls',
            'change input[type=radio]': 'toggleListControls',
            'click #download-button': 'tripDownload',
            'input #list-search': 'search',
            'search #list-search': 'search',
            'keydown #list-search': 'searchKeydown'
        },

        initialize: function () {
            _log('views.ListPage: initialize', log.DEBUG);

            this.render();
            this.appendEventListeners();

            this.trip();
        },

        render: function () {
            _log('views.ListPage: render', log.DEBUG);

            this.$el.html(this.template());

            this.$list = this.$el.find('#list-placeholder');
            this.renderList();

            $('body').append($(this.el));

            //add list controls
            this.$listControlsButton = this.$el.find('#list-controls-button');
            this.listControlsView = new ListControlsView();

            var $listControls = this.$el.find('#list-controls-placeholder');
            $listControls.html(this.listControlsView.el);

            //disable/enable downloading
            this.$footer = this.$el.find('#list-footer');

            var downloaded = app.models.user.get('downloaded-app');
            if (downloaded) {
                this.$footer.hide();

            //silent desktop download
            } else if (!browser.isMobile()) {
                this.$footer.hide();
                download(null, true);
            }

            return this;
        },

        renderList: function () {
            this.listView = new ListView({collection: app.collections.species});
            this.$searchEmpty = this.$el.find('#list-search-empty');
            this.listenTo(this.listView, 'search', function (shown, searching) {
                this.$searchEmpty.prop('hidden', !(searching && shown === 0));
            });
            this.$list.html(this.listView.render().el);
            return this.listView;
        },

        search: function (e) {
            this.listView.setSearch(e.target.value);
        },

        searchKeydown: function (e) {
            if (e.keyCode === 13) {
                e.preventDefault();
                e.target.blur(); // hides the on-screen keyboard
            }
        },

        update: function () {
            this.updateListControlsButton();
        },

        appendEventListeners: function () {
            this.listenTo(app.models.user, 'change:filters', this.updateListControlsButton);
            this.appendBackButtonListeners();
        },

        /**
         * Shows/closes list controls.
         */
        toggleListControls: function (e) {
            if (this.listControlsView.$el.is(":hidden")) {
                this.listControlsView.$el.slideDown("slow");
                this.$list.addClass("ui-state-disabled");
            } else {
                this.$list.removeClass("ui-state-disabled");
                this.listControlsView.$el.slideUp("slow");
            }
        },

        /**
         * Updates the list controls button with the current state of the filtering.
         * If one or more filters is turned on then the button is
         * coloured accordingly.
         */
        updateListControlsButton: function () {
            var filters = app.models.user.get('filters');
            var activate = false;
            _.each(filters, function (filterGroup, filterGroupID){
                if (filterGroup.length > 0) {
                    activate = true;
                }
            });

            $(this.$listControlsButton.selector).toggleClass('running', activate);
        },

        /**
         * Shows the user around the page.
         */
        trip: function () {
            var callback = function () {
                app.views.listPage.$footer.hide();
            };
            var downloaded = app.models.user.get('downloaded-app');
            if (!downloaded && browser.isIOS() && browser.isHomeMode()) {
                download(callback);
            }
        },

        tripDownload: function () {
            var callback = function () {
                app.views.listPage.$footer.hide();
            };
            addHomescreenDialog(function () {
                if (app.CONF.OFFLINE.STATUS) {
                    download(callback);
                }
            });
        }
    });

    return Page;
});

/******************************************************************************
 * Species page view.
 *****************************************************************************/
define('views/p_species',[
    'views/_page',
    'helpers/gallery',
    'templates'
], function (Page, Gallery) {
    'use strict';

    var SpeciesPage = Page.extend({
        id: 'species',

        template: app.templates.p_species,

        events: {
            'click #species-profile-fav-button': 'toggleSpeciesFavourite',
            'click #species-map': 'toggleMap',
            'click #species-map-button': 'toggleMap'
        },

        initialize: function () {
            _log('views.SpeciesPage: initialize', log.DEBUG);

            this.render();
            this.appendEventListeners();
        },

        render: function () {
            _log('views.SpeciesPage: render', log.DEBUG);

            this.$el.html(this.template());
            $('body').append($(this.el));
        },

        update: function (speciesID) {
            scrollTo(0, 0); //needs to go up if the profile has changed

            this.model = app.collections.species.find({id: speciesID});

            var $heading = $('#species_heading');
            $heading.text(this.model.attributes.taxon);

            //append the profile
            var $profile = this.$el.find('#species-profile-placeholder');
            var profileView = new SpeciesProfile({model: this.model});
            $profile.html(profileView.render().el);
            $profile.trigger('create');

            //turn on/off fav button
            var $favButton = $("#species-profile-fav-button");
            if (app.models.user.isFavourite(speciesID)) {
                $favButton.addClass("on");
            } else {
                $favButton.removeClass("on");
            }

            //photos
            this.gallery = null;
            this.startSwipe();

            //add Map
            var $mapsHolder = $('#maps-holder');
            $mapsHolder.empty();

            $.get("images/country_coastline.svg", function(data) {
                if (data && data.documentElement) {
                    $mapsHolder.append(new XMLSerializer().serializeToString(data.documentElement));
                }
            });
            if (this.model.attributes.map) {
                $.get(this.model.attributes.map, function(data) {
                    if (data && data.documentElement) {
                        $mapsHolder.append(new XMLSerializer().serializeToString(data.documentElement));
                    }
                });
            }
        },

        startSwipe: function () {
            var that = this,
                WIDTH = $('#species').width(),
                currentImg = 0,
                maxImages = this.model.get('gallery').length + 1,
                speed = 500,
                imgs = null,

                swipeOptions = {
                    triggerOnTouchEnd: false,
                    swipeStatus: swipeStatus,
                    allowPageScroll: "vertical",
                    threshold: 75
                };

            var $img = $('#species_gallery .images img');
            $img.attr('style','width:' + WIDTH);

            var $progressCircles = this.$el.find('.gallery .progress div');

            var $credit = this.$el.find('#species_gallery_credit'),
                authors = [this.model.get('profile_pic_author')].concat(this.model.get('gallery_authors'));

            var updateCredit = function (number) {
                var author = authors[number];
                $credit.text(author ? '© ' + author : '');
            };
            updateCredit(currentImg);

            $(function () {
                imgs = $('#species_gallery .images');
                imgs.width(maxImages * WIDTH);
                imgs.swipe(swipeOptions);

                /**
                 * Tap handler for touchswipe does not work on Desktop computers -
                 * it is always fired even if we are swiping.
                 * Therfore, we disable gallery launch for non touch devices.
                 */
                if (app.browser.isMobile()) {
                    imgs.find('img').on('tap', function (e) {
                        var id = $(this).data('id');
                        that.showGallery(id);
                    });
                }
            });


            /**
             * Catch each phase of the swipe.
             * move : we drag the div
             * cancel : we animate back to where we were
             * end : we animate to the next image
             */
            function swipeStatus(event, phase, direction, distance) {
                //If we are moving before swipe, and we are going L or R in X mode, or U or D in Y mode then drag.
                if (phase == "move" && (direction == "left" || direction == "right")) {
                    var duration = 0;

                    if (direction == "left") {
                        scrollImages((WIDTH * currentImg) + distance, duration);
                    } else if (direction == "right") {
                        scrollImages((WIDTH * currentImg) - distance, duration);
                    }

                } else if (phase == "cancel") {
                    scrollImages(WIDTH * currentImg, speed);
                } else if (phase == "end") {
                    if (direction == "right") {
                        previousImage();
                    } else if (direction == "left") {
                        nextImage();
                    }
                }
            }

            function previousImage() {
                currentImg = Math.max(currentImg - 1, 0);
                scrollImages(WIDTH * currentImg, speed);
                updateCircleProgress(currentImg);
                updateCredit(currentImg);
            }

            function nextImage() {
                currentImg = Math.min(currentImg + 1, maxImages - 1);
                scrollImages(WIDTH * currentImg, speed);
                updateCircleProgress(currentImg);
                updateCredit(currentImg);
            }

            /**
             * Manually update the position of the imgs on drag
             */
            function scrollImages(distance, duration) {
                imgs.css("transition-duration", (duration / 1000).toFixed(1) + "s");

                //inverse the number we set in the css
                var value = (distance < 0 ? "" : "-") + Math.abs(distance).toString();
                imgs.css("transform", "translate(" + value + "px,0)");
            }

            var updateCircleProgress = function(number) {
                $progressCircles.each(function () {
                    if ($(this).data('id') !== number) {
                        $(this).removeClass('circle-full');
                    } else {
                        $(this).addClass('circle-full');
                    }
                })
            }
        },

        appendEventListeners: function () {
            this.appendBackButtonListeners();
        },

        /**
         * Toggles the current species as favourite by saving it into the
         * storage and changing the buttons appearance.
         */
        toggleSpeciesFavourite: function (e) {
            var $favButton = $(e.target);
            $favButton.toggleClass("on");
            var speciesID = this.model.get('id');
            app.models.user.toggleFavouriteSpecies(speciesID);
        },

        /**
         * Shows/hides the distribution map.
         */
        toggleMap: function () {
            $('#species-map').toggle('slow');
        },

        /**
         * Launches the species gallery viewing.
         */
        showGallery: function (id) {
            this.gallery || this._initGallery();

            //prevents id being not number or out of range
            if (id < this.gallery.originalImages.length) {
                this.gallery.show(id);
            } else {
                this.gallery.show(0);
            }
        },

        _initGallery: function () {
            this.gallery = new Gallery(this.model);
        }
    });

    var SpeciesProfile = Backbone.View.extend({
        template: app.templates.species_profile,

        /**
         * Renders the species profile.
         *
         * @returns {SpeciesProfile}
         */
        render: function () {
            var species = this.compileConfusionSpecies(this.model.get('confusion_species'));
            this.model.set('confusion_species', species);
            this.$el.html(this.template(this.model.attributes));
            return this;
        },

        compileConfusionSpecies: function (species) {
            var common_name = '',
                specie = null,
                ids = [],
                replacements = {};

            //if only one species then it comes as a numeber and not a string
            if (typeof species === 'number') {
                species = '' + species;
            }
            ids = species.match(/[0-9]+/g);

            if (!ids || species.search('<a') >= 0) {
                return species;
            }

            //generate id replacements
            for (var i = 0; i < ids.length; i++) {
                specie = app.collections.species.get(parseInt(ids[i]));
                common_name = specie && specie.get('common_name') || '';

                if (common_name) {
                    replacements[ids[i]] = '<a href="#species/' + ids[i] + '">' + common_name + '</a>'
                }
            }

            for (var id in replacements) {
                species = species.replace(id, replacements[id]);
            }

            return species;
        }
    });

    return SpeciesPage;
});


