/******************************************************************************
 * User model. Persistent.
 *****************************************************************************/
define('models/user',[
    'backbone',
    'backbone.localStorage',
    'conf'
], function (Backbone) {
    'use strict';

    var User = Backbone.Model.extend({
        id: 'user',

        defaults: {
            name: '',
            surname: '',
            email: '',
            secret: '',
            locations: [],
            autosync: true,
            /* CSC - this overrided the default value defined in the scripts/conf.js
            sort: 'common_name',
            sortMulti: 'common_name',
            */
            sort: 'taxonomic',
            sortMulti: 'taxonomic',
            filters: {},
            filtersMulti: {},
            favourites: []
        },

        /**
         * Initializes the user.
         */
        initialize: function () {
            this.fetch();
        },

        localStorage: new Store(app.NAME),

        /**
         * Adds/removes favourite species ID from user information.
         *
         * @param speciesID
         */
        toggleFavouriteSpecies: function (speciesID) {
            var favourites = _.clone(this.get('favourites'));  //CLONING problem as discussed:
            //https://stackoverflow.com/questions/9909799/backbone-js-change-not-firing-on-model-change

            if (_.indexOf(favourites, speciesID) >= 0) {
                favourites = _.without(favourites, speciesID);
            } else {
                favourites.push(speciesID);
            }

            this.save('favourites', favourites);
        },

        /**
         * Checks if the speciesID belongs to user favourites.
         *
         * @param speciesID
         * @returns {boolean}
         */
        isFavourite: function (speciesID) {
            var favourites = this.get('favourites');
            return _.indexOf(favourites, speciesID) >= 0;
        },

        /**
         * Adds/removes species list filter from user information.
         *
         * @param filterID
         * @param groupID group the filter belongs to
         * @returns {boolean}
         */
        toggleListFilter: function (filterID, groupID, multi) {
            // var userFilters = _.clone(this.get('filters'));  //CLONING problem as discussed:
            //https://stackoverflow.com/questions/9909799/backbone-js-change-not-firing-on-model-change
            var filtersName = multi ? 'filtersMulti' : 'filters',
                userFilters = this.get(filtersName);

            var exists = false;
            if (userFilters[groupID]) {
                exists = userFilters[groupID].indexOf(filterID) >= 0;
                if (exists) {
                    userFilters[groupID] = _.without(userFilters[groupID], filterID);
                } else {
                    userFilters[groupID].push(filterID);
                }
            } else {
                userFilters[groupID] = [filterID];
            }

            this.set(filtersName, userFilters);
            this.save();
            this.trigger('change:' + filtersName);

            return !exists; //return the state of the filter added/removed
        },

        /**
         * Checks if the filterID belongs to user selected ones.
         *
         * @param filterID
         * @param filters
         * @returns {boolean}
         */
        groupHasListFilter: function (filterID, groupID, filters) {
            filters = filters || this.get('filters');
            return _.indexOf(filters[groupID], filterID) >= 0;
        },

        /**
         * @returns {boolean} Scientific or different type of sorting is selected
         */
        isSortScientific: function (multi) {
            var sort = this.get(multi ? 'sortMulti' : 'sort');
            return sort === 'scientific' || sort === 'scientific_r';
        }
    });

    return User;
});
/******************************************************************************
 * Main app router.
 *****************************************************************************/
define('routers/router',[
    'routers/router_extension',
    'views/_page',
    'views/p_welcome',
    'views/p_list',
    'views/p_species',
    'helpers/browser'
], function(ext, Page, WelcomePage, ListPage, SpeciesPage, browser) {
    'use strict';

    app.views = {};

    var Router = Backbone.Router.extend({
        /**
         * Initialize the router.
         */
        initialize: function () {
            _log('app.Router: initialize.', log.DEBUG);
        },

        /**
         * Routes to listen to.
         */
        routes: {
            "": function () {

                var trips = app.models.user.get('trips');

                if (!browser.isMobile() || (trips && (trips.indexOf('welcome') >= 0))) {
                    Backbone.history.navigate('list', {trigger: true});
                    return;
                }

                if (!app.views.welcomePage) {
                    app.views.welcomePage = new WelcomePage();
                }
                this.changePage(app.views.welcomePage);

                app.views.listPage = new ListPage();
                app.views.speciesPage = new SpeciesPage();
                app.views.infoPage = new Page('info');
            },

            "list(/:path)": {
                route: function () {
                    if (!app.views.listPage) {
                        app.views.listPage = new ListPage();
                    }
                    this.changePage(app.views.listPage);

                    app.views.listPage.update();
                },
                after: function () {
                    //leaving out safari home mode because it creates a nasty glitch on 8.3
                    if (!(browser.isIOS() && browser.isHomeMode())) {
                        var scroll = app.views.listPage.scroll;
                        if (scroll) {
                            window.scrollTo(0, scroll);
                        }
                    }
                },
                leave: function () {
                    app.views.listPage.scroll = $(window).scrollTop();
                }
            },

            "species/:id": function (id) {
                if (!app.views.speciesPage) {
                    app.views.speciesPage = new SpeciesPage();
                }
                this.changePage(app.views.speciesPage);

                app.views.speciesPage.update(parseInt(id));
            },

            "info": function () {
                this.navigateToStandardPage('info');
            },

            "about": function () {
                this.navigateToStandardPage('about');
            },

            "species-info": function () {
                this.navigateToStandardPage('species-info');
            },

            "species-differences": function () {
                this.navigateToStandardPage('species-differences');
            },

            "species-anatomy": function () {
                this.navigateToStandardPage('species-anatomy');
            },

            "species-terms": function () {
                this.navigateToStandardPage('species-terms');
            },

            "credits": function () {
                this.navigateToStandardPage('credits');
            }
        },

        /**
         * If the JQM page needs no controller and uses a rather static template
         * we can use this function to create the view and open it as a page.
         *
         * @param pageID the ID of a page that matches the template name
         */
        navigateToStandardPage: function (pageID) {
            if (!app.views[pageID + 'Page']) {
                app.views[pageID + 'Page'] = new Page(pageID);
            }
            this.changePage(app.views[pageID + 'Page']);
        },

        /**
         * Since the JQM page navigation is disabled with backbone this navigates to
         * a new page view.
         *
         * @param page backbone page view
         */
        changePage: function (page) {
            // We turned off $.mobile.autoInitializePage, but now that we've
            // added our first page to the DOM, we can now call initializePage.
            if (!this.initializedFirstPage) {
                _log('app.Router: loading first page.', log.DEBUG);

                $.mobile.initializePage();
                this.initializedFirstPage = true;
            }

            //update the URL hash
            $(":mobile-pagecontainer").pagecontainer("change", '#' + page.id,
                {changeHash: false});
        }
    });

    return Router;
});

/******************************************************************************
 * App model. Persistent.
 *****************************************************************************/
define('models/app',[
  'backbone',
  'backbone.localStorage',
  'conf'
], function (Backbone) {

  'use strict';

  var App = Backbone.Model.extend({

    id: 'app',

    localStorage: new Store(app.NAME),

    /**
     * Initializes the object.
     */
    initialize: function () {
      this.fetch();
      if (!this.get('appVer')) {
        this.save ('appVer', app.VERSION);
      }
    }
  });

  return App;
});
/******************************************************************************
 * Species collection.
 *****************************************************************************/
define('models/species',[
  'backbone'
], function (Backbone) {
  'use strict';

  var Specie = Backbone.Model.extend({
    defaults: {
      general: false,
      id: "",
      warehouse_id: 0,
      taxon: "",
      common_name: "",
      profile_pic: "images/unknown.png",
      description: "",
      distribution: "",
      habitat: "",
      map: "",
      gallery: [],
      colour: {},
      gallery_sex: [],
      profile_pic_sex: "",
      favourite: false
    }
  });

  var Species = Backbone.Collection.extend({
    model: Specie,

    /**
     * Initializes the collection.
     *
     * @param species Array
     */
    initialize: function (species) {
      this.listenTo(app.models.user, 'change', this.updateFavourites);

      // Udate the species with favourites for first time
      var favourites = app.models.user.get('favourites');
      _.each(species, function(specie){
        if (favourites.indexOf(specie.id) >= 0) {
          specie.favourite = true;
        } else {
          specie.favourite = false;
        }
      });
    },

    /**
     * Updates the object information about user favourite species.
     */
    updateFavourites: function () {
      var favourites = app.models.user.get('favourites');
      _.each(this.models, function(model){
        if (favourites.indexOf(model.get('id')) >= 0) {
          model.set('favourite', true);
        } else {
          model.set('favourite', false);
        }
      });
    }
  });

  return Species;
});
/******************************************************************************
 * Updates the app's data if the source code version mismatches the stored
 * data's version.
 *****************************************************************************/
define('helpers/update',[], function () {
    var CheckForUpdates = function () {
        var appVer = app.models.app.get('appVer');
        if (appVer !== app.VERSION) {
            _log('helpers: app version differs. Updating.', log.INFO);

            //set new version
            app.models.app.save('appVer', app.VERSION);
        }
    };

    return CheckForUpdates;
});

/******************************************************************************
 * Displays a self disappearing lightweight message.
 *****************************************************************************/
define('helpers/message',['jquery', 'jquery.mobile'], function ($, jqm) {

    $('body').append("<div class='ui-loader-background'> </div>");

    /**
     *
     * @param text
     * @param time 0 if no hiding, null gives default 3000ms delay
     * @constructor
     */
    var Message = function (text, time, callback) {
        var CLOSE_ID = 'loader-close',
            CLOSE_HTML = '<div id="' + CLOSE_ID + '" class="ui-btn ui-loader-close ui-icon-delete ui-btn-icon-notext ui-btn-right"></div>';

        if (!text) {
            _log('NAVIGATION: no text provided to message.', log.ERROR);
            return;
        }

        if (typeof text !== 'string') {
            text =
                "<h2>Sorry :(</h2>" +
                '<p>' +
                    (text.message || 'Some problem occurred') +
                    (text.number ? ' <small><i>(code: ' + text.number + ')</i></small>' : '') +
                '</p>';
        }

        var messageId = 'loaderMessage';
        var html = '<div id="' + messageId + '">' + (callback ? CLOSE_HTML : '') + text + '</div>';

        $.mobile.loading('show', {
            theme: "b",
            textVisible: true,
            textonly: true,
            html: html
        });

        //trigger JQM beauty
        $('#' + messageId).trigger('create');

        $('#' + CLOSE_ID).on('click', function () {
            $.mobile.loading('hide');
            typeof callback === 'function' && callback();
        });

        if (time !== 0) {
            setTimeout(function () {
                $.mobile.loading('hide');
            }, time || 3000);
        }
    };

    return Message;
});

/******************************************************************************
 * App object.
 *****************************************************************************/
define('app',[
        'jquery',
        'jquery.mobile',
        'backbone',
        'fastclick',
        'klass',
        'routers/router',
        'models/app',
        'models/user',
        'models/species',
        'helpers/update',
        'helpers/browser',
        'helpers/message',
        'helpers/log',
        'data'
    ],
    function ($, jqm, Backbone, FastClick, klass, Router, AppModel, UserModel,
              SpeciesCollection, update, browser, message) {
        var App = {
            init: function () {
                app.browser = browser;
                app.message = message;

                //init data
                app.models = {};
                app.models.user = new UserModel();
                app.models.app = new AppModel();
                app.collections = {};
                app.collections.species = new SpeciesCollection(app.data.species);

                //update app
                update();

                app.router = new Router();
                Backbone.history.start();

                FastClick.attach(document.body);

                //turn off the loading splash screen
                $('div.loading').css('display', 'none');
                $('body').removeClass('loading');
            }
        };
        return App;
    });
